# Check if anti-diagonals in demo input have constant colors
def get_diag_values(grid, s):
    """Get all values on anti-diagonal r+c = s"""
    vals = []
    for r in range(len(grid)):
        c = s - r
        if 0 <= c < len(grid[r]):
            vals.append((r, c, grid[r][c]))
    return vals

for s in range(14):
    values = get_diag_values(demo_input, s)
    non_zero = [v[2] for v in values if v[2] != 0]
    if non_zero:
        print(f"Sum {s}: {non_zero[:5]}... (has {len(values)} positions)")

